import React, { useState, useEffect, useMemo, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { 
  Search, SlidersHorizontal, Star, Plus, Minus, Home, LayoutGrid, Tag, Info, Heart
} from 'lucide-react';
import { categories, products, offers } from './data/menu';

// Premium Food Images for Categories (Toing Style)
const categoryImages = {
  all: "https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=150&q=80",
  sandwich: "https://images.unsplash.com/photo-1528735602780-2552fd46c7af?auto=format&fit=crop&w=150&q=80",
  jain: "https://images.unsplash.com/photo-1546069901-ba9599a7e63c?auto=format&fit=crop&w=150&q=80",
  grill: "https://images.unsplash.com/photo-1539252554452-da6aec9d11f4?auto=format&fit=crop&w=150&q=80",
  'special-grill': "https://images.unsplash.com/photo-1481061742414-aebb192e9dc7?auto=format&fit=crop&w=150&q=80",
  'jumbo-grill': "https://images.unsplash.com/photo-1565299624946-b28f40a0ae38?auto=format&fit=crop&w=150&q=80",
  pizza: "https://images.unsplash.com/photo-1513104890138-7c749659a591?auto=format&fit=crop&w=150&q=80",
  burger: "https://images.unsplash.com/photo-1568901346375-23c9450c58cd?auto=format&fit=crop&w=150&q=80",
  paratha: "https://images.unsplash.com/photo-1626776876729-bab4369a5a54?auto=format&fit=crop&w=150&q=80",
  khulcha: "https://images.unsplash.com/photo-1601050690597-df0568f70950?auto=format&fit=crop&w=150&q=80",
  frankie: "https://images.unsplash.com/photo-1589135398309-1144c5b16e15?auto=format&fit=crop&w=150&q=80",
  'hot-dog': "https://images.unsplash.com/photo-1541214113241-21578d2d9b62?auto=format&fit=crop&w=150&q=80",
  'french-fries': "https://images.unsplash.com/photo-1573080496219-bb080dd4f877?auto=format&fit=crop&w=150&q=80",
  'garlic-bread': "https://images.unsplash.com/photo-1573140247632-f8fd74997d5c?auto=format&fit=crop&w=150&q=80",
  juices: "https://images.unsplash.com/photo-1600271886342-ad92c39b95a9?auto=format&fit=crop&w=150&q=80",
  beverages: "https://images.unsplash.com/photo-1499638673689-79a0b5115d87?auto=format&fit=crop&w=150&q=80",
  extras: "https://images.unsplash.com/photo-1585238342024-78d387f4a707?auto=format&fit=crop&w=150&q=80",
};

const App = () => {
  const [activeCategory, setActiveCategory] = useState('all');
  const [sandwichOnly, setSandwichOnly] = useState(false);
  const [cart, setCart] = useState({});
  const [searchQuery, setSearchQuery] = useState('');
  const [scrolled, setScrolled] = useState(false);
  const [activeOffer, setActiveOffer] = useState(0);
  const offerRef = useRef(null);

  useEffect(() => {
    const handleScroll = () => setScrolled(window.scrollY > 20);
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  // Auto-slide offers
  useEffect(() => {
    const timer = setInterval(() => {
      setActiveOffer((prev) => (prev + 1) % offers.length);
    }, 4000);
    return () => clearInterval(timer);
  }, []);

  useEffect(() => {
    if (offerRef.current) {
      offerRef.current.scrollTo({
        left: activeOffer * (offerRef.current.offsetWidth - 40),
        behavior: 'smooth'
      });
    }
  }, [activeOffer]);

  const filteredProducts = useMemo(() => {
    return products.filter(product => {
      const matchesCategory = activeCategory === 'all' || product.category === activeCategory;
      const matchesSearch = product.name.toLowerCase().includes(searchQuery.toLowerCase());
      const isSandwichRelated = ['sandwich', 'grill', 'special-grill', 'jumbo-grill'].includes(product.category);
      const matchesSandwichToggle = !sandwichOnly || isSandwichRelated;

      return matchesCategory && matchesSearch && matchesSandwichToggle;
    });
  }, [activeCategory, searchQuery, sandwichOnly]);

  const updateCart = (id, delta) => {
    setCart(prev => {
      const newQty = (prev[id] || 0) + delta;
      if (newQty <= 0) {
        const { [id]: _, ...rest } = prev;
        return rest;
      }
      return { ...prev, [id]: newQty };
    });
  };

  return (
    <div className="max-w-[480px] mx-auto min-h-screen bg-background pb-32 selection:bg-primary/20 font-sans">
      {/* 1. HEADER REDESIGN - BRAND FOCUSED */}
      <header className={`fixed top-0 left-0 right-0 z-[60] transition-all duration-500 ${
        scrolled ? 'bg-white/80 backdrop-blur-xl py-2 shadow-sm' : 'bg-transparent py-4'
      }`}>
        <div className="max-w-[480px] mx-auto px-5 flex items-center justify-center">
          <motion.img 
            layout
            src="/logo.webp" 
            alt="Restaurant Logo" 
            className={`${scrolled ? 'h-10' : 'h-14'} w-auto object-contain transition-all duration-300`}
          />
        </div>
      </header>

      <main className="pt-24 px-5">
        {/* 2. SEARCH BAR + SANDWICH TOGGLE (Toing Style) */}
        <section className="mb-8 flex items-center gap-2">
          <div className="relative flex-[0.85] group">
            <div className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 group-focus-within:text-primary transition-colors">
              <Search size={18} />
            </div>
            <input 
              type="text"
              placeholder="Search dishes..."
              className="w-full bg-white h-12 pl-11 pr-4 rounded-2xl shadow-[0_4px_20px_rgb(0,0,0,0.03)] border border-slate-100 focus:border-primary/20 focus:ring-4 focus:ring-primary/5 transition-all outline-none text-slate-700 text-sm font-medium placeholder:text-slate-300"
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
            />
          </div>

          <button 
            onClick={() => setSandwichOnly(!sandwichOnly)}
            className={`flex items-center gap-1.5 p-1 pr-2 rounded-full transition-all duration-300 border flex-[0.15] min-w-[48px] justify-center ${
              sandwichOnly 
              ? 'bg-primary border-primary text-white shadow-lg shadow-primary/20' 
              : 'bg-white border-slate-100 text-slate-400'
            }`}
          >
            <div className="text-base">🥪</div>
            <div className={`w-6 h-3.5 rounded-full relative border ${sandwichOnly ? 'bg-white/20 border-white/30' : 'bg-slate-200 border-slate-300'}`}>
              <motion.div 
                animate={{ x: sandwichOnly ? 11 : 1 }}
                className={`absolute top-0.5 w-2 h-2 rounded-full ${sandwichOnly ? 'bg-white' : 'bg-slate-400'}`}
              />
            </div>
          </button>
        </section>

        {/* OFFERS HERO (Unchanged business logic) */}
        <section className="mb-10 -mx-5 overflow-hidden">
          <div 
            ref={offerRef}
            className="flex gap-4 overflow-x-auto no-scrollbar px-5 py-2 scroll-smooth"
          >
            {offers.map((offer, i) => (
              <motion.div 
                key={offer.id}
                whileTap={{ scale: 0.97 }}
                className="min-w-[85%] h-44 rounded-3xl relative overflow-hidden shadow-xl"
              >
                <img src={offer.image} alt={offer.title} className="absolute inset-0 w-full h-full object-cover" />
                <div className={`absolute inset-0 bg-gradient-to-r ${offer.color.replace('bg-', 'from-')}/80 to-transparent flex flex-col justify-center px-8`}>
                  <h3 className="text-white font-black text-2xl leading-none mb-1">{offer.title}</h3>
                  <p className="text-white/90 text-sm font-bold">{offer.subtitle}</p>
                </div>
              </motion.div>
            ))}
          </div>
          <div className="flex justify-center gap-2 mt-5">
            {offers.map((_, i) => (
              <motion.div 
                key={i} 
                animate={{ width: i === activeOffer ? 24 : 8 }}
                className={`h-2 rounded-full transition-colors duration-300 ${i === activeOffer ? 'bg-primary' : 'bg-slate-200'}`} 
              />
            ))}
          </div>
        </section>

        {/* 3, 4, 5, 6. CATEGORY SECTION REDESIGN */}
        <section className="mb-10">
          <div className="flex items-center justify-between mb-4">
            <h2 className="font-bold text-lg text-slate-800 tracking-tight">Top Categories</h2>
            <button className="text-primary text-xs font-bold uppercase tracking-widest">See All</button>
          </div>
          <div className="flex gap-4 overflow-x-auto no-scrollbar -mx-5 px-5 h-[140px] items-center snap-x snap-mandatory">
            {categories.map((cat) => (
              <motion.button
                key={cat.id}
                whileTap={{ scale: 0.95 }}
                onClick={() => setActiveCategory(cat.id)}
                className={`flex flex-col items-center justify-center min-w-[100px] h-[120px] rounded-[24px] transition-all duration-300 snap-center border-2 ${
                  activeCategory === cat.id 
                  ? 'bg-white border-primary shadow-xl shadow-primary/10' 
                  : 'bg-white border-transparent shadow-sm'
                }`}
              >
                <div className="w-16 h-16 rounded-full overflow-hidden mb-2">
                  <img 
                    src={categoryImages[cat.id] || categoryImages.all} 
                    alt={cat.name}
                    className="w-full h-full object-cover transition-transform duration-500 hover:scale-110"
                    loading="lazy"
                  />
                </div>
                <span className={`text-[11px] font-bold uppercase tracking-wide text-center leading-tight px-1 ${
                  activeCategory === cat.id ? 'text-primary' : 'text-slate-500'
                }`}>
                  {cat.name}
                </span>
                {activeCategory === cat.id && (
                  <motion.div layoutId="categoryIndicator" className="w-1.5 h-1.5 bg-primary rounded-full mt-1" />
                )}
              </motion.button>
            ))}
          </div>
        </section>

        {/* STICKY FILTER CHIPS */}
        <div className="sticky top-[60px] z-40 bg-background/95 backdrop-blur-md -mx-5 px-5 py-3 mb-6 flex gap-2 overflow-x-auto no-scrollbar border-y border-slate-100/50">
          {['⭐ Best Sellers', '🔥 Popular', '₹ Under 99', '🧀 Cheese', '🌶️ Spicy'].map((chip) => (
            <motion.button 
              key={chip}
              whileTap={{ scale: 0.95 }}
              className="px-4 py-2 bg-white border border-slate-100 rounded-full whitespace-nowrap text-[11px] font-bold text-slate-600 shadow-sm"
            >
              {chip}
            </motion.button>
          ))}
        </div>

        {/* PRODUCT LIST (Toing Inspired) */}
        <section className="grid grid-cols-2 gap-4 mb-10">
          <AnimatePresence mode='popLayout'>
            {filteredProducts.map((product) => (
              <motion.div
                layout
                initial={{ opacity: 0, scale: 0.97 }}
                animate={{ opacity: 1, scale: 1 }}
                exit={{ opacity: 0, scale: 0.9 }}
                whileHover={{ y: -5 }}
                key={product.id}
                className="bg-white rounded-[24px] p-3 shadow-[0_8px_30px_rgb(0,0,0,0.04)] transition-all duration-300 flex flex-col h-full"
              >
                {/* Image */}
                <div className="relative aspect-square rounded-[24px] overflow-hidden mb-3 bg-slate-100">
                  <motion.img 
                    whileHover={{ scale: 1.1 }}
                    transition={{ duration: 0.6 }}
                    src={`https://images.unsplash.com/photo-${1500000000000 + product.id}?auto=format&fit=crop&w=400&q=80`} 
                    alt={product.name}
                    loading="lazy"
                    className="w-full h-full object-cover"
                    onError={(e) => {
                      e.target.src = "https://images.unsplash.com/photo-1528735602780-2552fd46c7af?auto=format&fit=crop&w=400&q=80";
                    }}
                  />

                  {/* Badges Overlay */}
                  <div className="absolute top-2 left-2 flex flex-col gap-1 items-start">
                    {product.rating >= 4.8 && (
                      <span className="bg-orange-500 text-white text-[7px] font-bold px-1.5 py-0.5 rounded-full uppercase tracking-tighter shadow-sm">Best Seller</span>
                    )}
                    {product.veg && (
                      <div className="w-3.5 h-3.5 border border-green-600 flex items-center justify-center bg-white/90 backdrop-blur-sm rounded-[3px] shadow-sm">
                        <div className="w-1 h-1 bg-green-600 rounded-full" />
                      </div>
                    )}
                  </div>

                  <button className="absolute top-2 right-2 p-1.5 bg-white/90 backdrop-blur-sm rounded-full text-slate-300 hover:text-red-500 transition-colors shadow-sm">
                    <Heart size={12} />
                  </button>
                </div>

                {/* Content */}
                <div className="flex-1 flex flex-col">
                  <h3 className="font-semibold text-[15px] text-slate-800 line-clamp-2 leading-tight mb-1">
                    {product.name}
                  </h3>
                  <p className="text-[11px] text-slate-400 line-clamp-2 leading-tight mb-3">
                    {product.description}
                  </p>

                  <div className="mt-auto flex items-center justify-between">
                    <div className="flex flex-col">
                      <div className="flex items-center gap-1 mb-0.5">
                        <div className="bg-emerald-50 text-emerald-600 px-1 py-0.5 rounded flex items-center gap-0.5">
                          <Star size={8} className="fill-emerald-600" />
                          <span className="text-[9px] font-black">{product.rating}</span>
                        </div>
                      </div>
                      <span className="font-bold text-slate-900 text-[16px]">₹{product.price}</span>
                    </div>

                    <div className="relative">
                      <AnimatePresence mode='wait'>
                        {cart[product.id] ? (
                          <motion.div 
                            key="qty"
                            layout
                            initial={{ width: 32, opacity: 0 }}
                            animate={{ width: 70, opacity: 1 }}
                            exit={{ width: 32, opacity: 0 }}
                            className="flex items-center bg-primary text-white rounded-full h-8 p-0.5 shadow-lg shadow-primary/20"
                          >
                            <button 
                              onClick={() => updateCart(product.id, -1)}
                              className="w-6 h-6 flex items-center justify-center hover:bg-white/20 rounded-full"
                            >
                              <Minus size={12} strokeWidth={3} />
                            </button>
                            <span className="flex-1 text-center font-bold text-xs">{cart[product.id]}</span>
                            <button 
                              onClick={() => updateCart(product.id, 1)}
                              className="w-6 h-6 flex items-center justify-center hover:bg-white/20 rounded-full"
                            >
                              <Plus size={12} strokeWidth={3} />
                            </button>
                          </motion.div>
                        ) : (
                          <motion.button
                            key="add"
                            layout
                            initial={{ opacity: 0, scale: 0.8 }}
                            animate={{ opacity: 1, scale: 1 }}
                            whileTap={{ scale: 0.9 }}
                            onClick={() => updateCart(product.id, 1)}
                            className="w-8 h-8 bg-primary text-white flex items-center justify-center rounded-full shadow-lg shadow-primary/20"
                          >
                            <Plus size={18} strokeWidth={3} />
                          </motion.button>
                        )}
                      </AnimatePresence>
                    </div>
                  </div>
                </div>
              </motion.div>
            ))}
          </AnimatePresence>
        </section>

        <div className="h-20 flex flex-col items-center justify-center opacity-30">
          <Info size={16} className="mb-2" />
          <p className="text-[9px] font-bold uppercase tracking-[0.2em]">End of Menu</p>
        </div>
      </main>

      {/* BOTTOM NAVIGATION (Unchanged logic) */}
      <nav className="fixed bottom-8 left-1/2 -translate-x-1/2 w-[92%] max-w-[440px] bg-slate-900/95 backdrop-blur-2xl rounded-[32px] p-2 flex items-center justify-between shadow-2xl z-[100]">
        {[
          { id: 'home', icon: Home, label: 'Home' },
          { id: 'categories', icon: LayoutGrid, label: 'Browse' },
          { id: 'offers', icon: Tag, label: 'Deals' },
        ].map((item) => {
          const isActive = item.id === 'home';
          const ShoppingCartIcon = item.icon;
          return (
            <motion.button
              key={item.id}
              whileTap={{ scale: 0.9 }}
              className={`relative flex items-center gap-2 px-4 py-3 rounded-[24px] transition-all duration-300 ${
                isActive ? 'bg-primary text-white shadow-lg' : 'text-slate-500'
              }`}
            >
              <item.icon size={18} strokeWidth={isActive ? 3 : 2} />
              {isActive && <span className="text-xs font-bold tracking-tight">{item.label}</span>}
              {item.count > 0 && !isActive && (
                <span className="absolute top-1.5 right-2 w-4 h-4 bg-primary text-white text-[8px] font-black rounded-full flex items-center justify-center border border-slate-900">
                  {item.count}
                </span>
              )}
            </motion.button>
          );
        })}
      </nav>

      {/* OVERLAY TEXTURE */}
      <div className="fixed inset-0 pointer-events-none z-[200]">
        <div className="w-full h-full opacity-[0.02] bg-[url('https://www.transparenttextures.com/patterns/asfalt-dark.png')]" />
      </div>
    </div>
  );
};

export default App;
